insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  '27e17f32-190d-5db1-a797-f86d706088ae', $q$optistruct$q$, $q$*** ERROR # 1953：模型存在剛體模態，線性靜態分析無法求解$q$, array[$q$solver-error$q$, $q$boundary-condition$q$, $q$rigid-body$q$]::text[],
  $q$執行 Linear Static 時 solver 在組裝剛度矩陣後中止：
`*** ERROR # 1953: The model has rigid body modes.`
.out 檔列出 grid 120334 自由度 1、2、6 無約束。$q$,
  $q$左右支架以 `RBE2` 連接到螺栓，但螺栓本體只有 1D `CBAR`，旋轉自由度沒有傳到殼元素；另外 SPC 只拘束了 T1–T3。$q$,
  $q$1. 用 **Tools › Model Checker** 找出未連接的 component
2. 在螺栓兩端補 `RBE2`，dependent DOF 設 `123456`
3. 先跑 `PARAM,CHECKEL,YES` + `PARAM,GRDPNT,0` 確認質量與約束
4. 仍不確定時加 `PARAM,INREL,-2` 做慣性釋放檢查$q$,
  array[$q$增加 SPC 到 123456 —— 反而把真實邊界條件改掉了$q$, $q$把 AUTOSPC 關掉$q$]::text[], $q$常見於組件拼裝後第一次提交，建議把 Model Checker 變成提交前的固定步驟。$q$, $q$Altair OptiStruct Help — Rigid Body Modes$q$,
  $q$[]$q$::jsonb, 0, '2026-09-27T17:51:30.052Z', '2026-09-30T17:51:30.053Z')
