insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  '14528e61-1116-548e-9ab7-65916ede4195', $q$optistruct$q$, $q$Insufficient memory：大型模型求解時記憶體不足$q$, array[$q$solver-error$q$, $q$performance$q$, $q$memory$q$]::text[],
  $q$約 480 萬自由度的模型在 `SOLVE` 階段中止，訊息為 `Insufficient memory allocated, increase -len`。$q$,
  $q$預設 `-len` 太小，且 out-of-core 暫存資料夾指到網路磁碟，I/O 太慢。$q$,
  $q$- 提交參數加上 `-len 32000 -core in`
- 若記憶體不足以 in-core，改 `-core out` 並把 `-tmpdir` 指到本機 SSD
- 使用 `-nt 8` 開啟平行運算$q$,
  '{}'::text[], $q$先用 `-check` 跑一次，.out 會估算 in-core 所需記憶體。$q$, $q$Altair Help / Internal HPC Guide$q$,
  $q$[]$q$::jsonb, 0, '2026-09-26T13:03:30.053Z', '2026-09-29T13:03:30.053Z')
