insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  '811fa4ed-60a8-5462-8e3a-aea3106e8c6c', $q$optistruct$q$, $q$拓樸最佳化結果出現棋盤格（checkerboard）$q$, array[$q$optimization$q$, $q$mesh-quality$q$]::text[],
  $q$密度結果呈現黑白交錯的棋盤格，無法轉成可製造的幾何。$q$,
  $q$沒有設定最小尺寸控制 `MINDIM`，網格尺寸與設計特徵尺寸接近。$q$,
  $q$1. `DTPL` 加上 `MINDIM`，約為平均元素尺寸的 3 倍
2. 視需求加 `MAXDIM` 與製造限制（`DRAW`、`EXTR`）
3. 以 `DISCRETE` 2.0–3.0 提高 0/1 收斂度$q$,
  array[$q$只把網格加密 —— 棋盤格變細但沒有消失$q$]::text[], $q$$q$, $q$$q$,
  $q$[]$q$::jsonb, 0, '2026-09-24T22:39:30.053Z', '2026-09-27T22:39:30.053Z')
