insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  'c0a82511-6795-5e26-9b10-f953022670f5', $q$hypermesh-2$q$, $q$STEP 匯入後幾何破面，free edges 無法補面$q$, array[$q$geometry$q$, $q$cleanup$q$, $q$step$q$]::text[],
  $q$CAD 匯入後出現破面、縫隙，無法產生封閉 mid-surface 或 solid map。Geometry › Free edges 顯示紅色邊界約 120 條。$q$,
  $q$CAD 輸出公差（0.01 mm）小於 HyperMesh 的 cleanup tolerance，縫合沒有成功。$q$,
  $q$1. **Geometry › Autocleanup** 前先把 cleanup tol 設成 0.1
2. 使用 **Edge Edit › Toggle / Equivalence** 合併重複邊
3. 仍開口的區域用 **Surface › Fill** 補面，再 `Stitch`$q$,
  array[$q$重新匯出 IGES —— 破面更多$q$]::text[], $q$請 CAD 端以 AP214 輸出、公差 0.001 mm，品質明顯較好。$q$, $q$Altair HyperMesh Help — Geometry Cleanup$q$,
  $q$[{"src":"assets/figures/fig-01-free-edges.svg","title":"Free edges 顯示紅色邊界","caption":"Geometry › Free edges：匯入後約 120 條自由邊（紅），集中在曲面交界。","section":"symptom","step":0,"order":1,"key":true,"mock":true},{"src":"assets/figures/fig-02-cleanup-tolerance.svg","title":"間隙與 cleanup tolerance","caption":"CAD 間隙約 0.01 mm，超出預設 tol，因此無法自動縫合。","section":"root_cause","step":0,"order":2,"mock":true},{"src":"assets/figures/fig-03-autocleanup-panel.svg","title":"Autocleanup：cleanup tol = 0.1","caption":"先把 cleanup tol 由預設值調為 0.1 再執行。","section":"solution","step":1,"order":3,"mock":true},{"src":"assets/figures/fig-04-edge-equivalence.svg","title":"Edge Edit：合併重複邊","caption":"Toggle / Equivalence 合併重複邊，紅線會轉為綠線。","section":"solution","step":2,"order":4,"mock":true},{"src":"assets/figures/fig-05-surface-fill-stitch.svg","title":"Surface Fill + Stitch","caption":"仍開口的區域補面後再 Stitch。","section":"solution","step":3,"order":5,"mock":true},{"src":"assets/figures/fig-06-before-after.svg","title":"修補前 / 修補後","caption":"free edges 由 120 降至 2，剩餘兩條為倒角尖點。","section":"solution","step":"v","order":6,"mock":true},{"src":"assets/figures/fig-07-autocleanup-warning.svg","title":"Autocleanup 警告訊息","caption":"12 個 surface 縫合失敗；tolerance 小於邊界間隙。","section":"symptom","step":0,"order":7,"mock":true},{"src":"assets/figures/fig-08-mesh-quality.svg","title":"修補後 2D 網格品質","caption":"Jacobian ≥ 0.6 達 99.1%，可繼續產生 solid map。","section":"solution","step":"v","order":8,"mock":true}]$q$::jsonb, 0, '2026-09-27T05:51:30.053Z', '2026-09-30T05:51:30.053Z')
