insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  'ccec1f92-2b8c-51d2-be28-c1edbccdc978', $q$hypermesh-2$q$, $q$Mid-surface 抽取失敗：肋條厚度不一致$q$, array[$q$geometry$q$, $q$midsurface$q$]::text[],
  $q$`Midsurface › Auto Extract` 在薄肋與主體交界處產生缺口，部分肋條沒有被抽出。$q$,
  $q$肋條有拔模角，厚度從 1.8 mm 漸變到 2.6 mm，自動辨識的 thickness pair 不一致。$q$,
  $q$- 改用 **Surface Pair** 手動指定上下面
- 對拔模肋條使用 **Offset** 後再 `Extend` 接回主面
- 厚度以 `Assign thickness from midsurface` 自動回填$q$,
  '{}'::text[], $q$$q$, $q$$q$,
  $q$[]$q$::jsonb, 0, '2026-09-25T17:51:30.053Z', '2026-09-28T17:51:30.053Z')
