insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  '11bcbed1-1651-5208-b298-cf1ebcdedcec', $q$hypermesh-2$q$, $q$Element quality：Jacobian < 0.6 無法通過品質檢查$q$, array[$q$mesh-quality$q$, $q$jacobian$q$]::text[],
  $q$倒角附近的 2D 元素 Jacobian 低於 0.6，約 340 個元素無法通過品質門檻。$q$,
  $q$倒角寬度小於網格尺寸，四邊形元素被壓扁。$q$,
  $q$1. 對小倒角使用 **Defeature › Fillets** 或改成 2 排元素
2. 以 **2D › Qualityindex** 設定目標後執行 `Clean up`
3. 局部改用 trias，比例控制在 5% 以內$q$,
  '{}'::text[], $q$$q$, $q$$q$,
  $q$[]$q$::jsonb, 0, '2026-09-22T22:39:30.053Z', '2026-09-25T22:39:30.053Z')
