insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  '13dd25e0-2c7a-5c6e-a6f2-96363c0f1f88', $q$lsdyna$q$, $q$Negative volume in solid element — 計算中止$q$, array[$q$solver-error$q$, $q$contact$q$, $q$mesh-quality$q$]::text[],
  $q$約 18 ms 時 d3hsp 顯示：
`*** Error 40509 (SOL+509) negative volume in solid element # 2004871`
隨後計算中止。$q$,
  $q$泡棉材料（`*MAT_057`）在大變形下元素嚴重扭曲，且與鋼板之間的接觸剛度不足。$q$,
  $q$1. 泡棉 part 改用 `ELFORM=-1` 或 `ELFORM=-2`
2. 加入 `*CONTACT_INTERIOR` 防止元素翻轉
3. `*CONTROL_SOLID` 設 `ERODE=1`，`*CONTROL_TIMESTEP` 設 `DTMIN`
4. 接觸改 `SOFT=2`$q$,
  array[$q$單純降低時間步長 —— 只延後錯誤出現的時間$q$]::text[], $q$先檢查是否為局部初始穿透造成的扭曲。$q$, $q$LS-DYNA Keyword Manual Vol. I / Internal Test$q$,
  $q$[]$q$::jsonb, 0, '2026-09-27T13:03:30.053Z', '2026-09-30T13:03:30.053Z')
