insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  'f4450e15-f6e1-5a5c-b880-3242c1db4292', $q$lsdyna$q$, $q$Hourglass energy 超過 internal energy 的 10%$q$, array[$q$energy$q$, $q$mesh-quality$q$, $q$hourglass$q$]::text[],
  $q$glstat 中 hourglass energy 在 30 ms 後持續上升，最後約為 internal energy 的 14%。$q$,
  $q$大量使用 `ELFORM=2` 單點積分殼元素，且未設定 hourglass 控制。$q$,
  $q$- `*HOURGLASS` 使用 `IHQ=4`（剛度型），`QM=0.05`
- 高應變區改用 `ELFORM=16` 全積分殼
- 以 `*DATABASE_MATSUM` 找出能量集中的 part$q$,
  '{}'::text[], $q$判斷標準：HG / IE < 10%，局部 part 最好 < 5%。$q$, $q$$q$,
  $q$[]$q$::jsonb, 0, '2026-09-26T01:03:30.053Z', '2026-09-29T01:03:30.053Z')
