insert into public.entries (id, category, title, tags, symptom, root_cause, solution, failed_attempts, notes, reference_source, images, views, created_at, updated_at) values (
  '29206e83-6d69-520a-bd61-9f338f4fcec9', $q$lsdyna$q$, $q$*CONTACT 初始穿透警告（initial penetration）$q$, array[$q$contact$q$, $q$geometry$q$]::text[],
  $q$messag 出現大量 `Warning 30204: initial penetration`，部分節點被移動。$q$,
